193:        return String.join(",", figures.entrySet().stream()
194:                .map(e -> e.getKey() + "=" + e.getValue().toPlainString()).toList());
195:    }
196:
197:    /** Figures by person id read back from {@link #pairs}. */
198:    private static Map<Long, BigDecimal> unpair(String kept) {
199:        Map<Long, BigDecimal> figures = new LinkedHashMap<>();
200:        if (kept != null && !kept.isEmpty()) {
201:            for (String pair : kept.split(",")) {
202:                String[] parts = pair.split("=");
203:                figures.put(Long.valueOf(parts[0]), new BigDecimal(parts[1]));
204:            }
205:        }
206:        return figures;
207:    }
208:
209:    /** The sheet's periods as they stood at the end of a day, by period id; a period saved only after
210:     *  it, or before their states were kept, is absent. */
211:    public Map<Long, PeriodThen> periods(String sheetId, LocalDate day) {
212:        Map<Long, PeriodThen> then = new LinkedHashMap<>();
213:        jdbc.query("SELECT * FROM period_history WHERE sheet_id = ? AND made_on <= ? ORDER BY id", (rs, n) ->
214:                new PeriodThen(rs.getLong("period_id"), rs.getString("name"),
215:                        rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class),
216:                        rs.getBoolean("closed"), rs.getBoolean("soft_closed"), rs.getBigDecimal("closed_total"),
217:                        unpair(rs.getString("person_totals")), unpair(rs.getString("person_carried"))),
218:                sheetId, day).forEach(period -> then.put(period.id(), period));
219:        return then;
220:    }
221:
222:    /** Keep a value set for a sheet setting that is not dated (null: blank), with the sheet's today. */
223:    public void settingSet(String sheetId, String key, String value) {
224:        jdbc.update("INSERT INTO sheet_setting_history (sheet_id, setting_key, setting_value, made_on)"
225:                + " SELECT id, ?, ?, today FROM sheet WHERE id = ?", key, value, sheetId);
226:    }
227:
228:    /** The values of the sheet's settings that are not dated as they stood set at the end of a day, by
229:     *  key (a value null for blank); a key never set by then is absent. */
230:    public Map<String, String> settings(String sheetId, LocalDate day) {
231:        Map<String, String> then = new LinkedHashMap<>();
232:        jdbc.query("SELECT setting_key, setting_value FROM sheet_setting_history WHERE sheet_id = ? AND made_on <= ?"
233:                        + " ORDER BY id",
234:                (rs, n) -> new String[] {rs.getString("setting_key"), rs.getString("setting_value")},
235:                sheetId, day).forEach(pair -> then.put(pair[0], pair[1]));
236:        return then;
237:    }
238:
239:    /** The keys of the sheet's settings that are not dated whose values were ever kept. */
240:    public List<String> settingsKept(String sheetId) {
241:        return jdbc.queryForList("SELECT DISTINCT setting_key FROM sheet_setting_history WHERE sheet_id = ?",
242:                String.class, sheetId);
243:    }
244:
245:    /** A grade's rates on the sheet as they stood at the end of a day: for each from-date, the rate
246:     *  last set from it by then, with the ones set from it before, newest first, as its earlier
247:     *  versions. */
248:    public List<Rate> rates(String sheetId, String grade, LocalDate day) {
249:        Map<LocalDate, List<Rate>> byFrom = new LinkedHashMap<>();
250:        jdbc.query("SELECT * FROM rate_history WHERE sheet_id = ? AND grade = ? AND made_on <= ? ORDER BY id",
251:                (rs, n) -> new Rate(sheetId, grade, rs.getObject("from_date", LocalDate.class),
252:                        rs.getObject("to_date", LocalDate.class), rs.getBigDecimal("rate"), rs.getInt("version"),
253:                        rs.getObject("forward_after", Long.class)),
254:                sheetId, grade, day).forEach(rate -> byFrom.computeIfAbsent(rate.getFrom(), from -> new ArrayList<>())
255:                        .add(0, rate));
256:        return byFrom.values().stream().map(set -> {
257:            Rate last = set.get(0);
258:            last.setEarlier(set.subList(1, set.size()));
259:            return last;
260:        }).toList();
261:    }
262:
263:    /** A person's grades as they stood at the end of a day: for each from-date, the grade last given
264:     *  from it by then. */
265:    public List<PersonGrade> grades(Long personId, LocalDate day) {
266:        Map<LocalDate, PersonGrade> byFrom = new LinkedHashMap<>();
267:        jdbc.query("SELECT * FROM person_grade_history WHERE person_id = ? AND made_on <= ? ORDER BY id",
268:                (rs, n) -> new PersonGrade(rs.getString("sheet_id"), personId, rs.getString("grade"),
269:                        rs.getObject("from_date", LocalDate.class)),
270:                personId, day).forEach(grade -> byFrom.put(grade.getFrom(), grade));
271:        return new ArrayList<>(byFrom.values());
272:    }
273:
274:    /** The value of a dated setting in force on a date as the values stood at the end of a day: of
275:     *  the value last recorded from each from-date by then, the one with the latest from-date on or
276:     *  before the date; empty before every from-date. */
277:    public Optional<SettingValue> setting(String sheetId, String key, LocalDate on, LocalDate day) {
278:        Map<LocalDate, SettingValue> byFrom = new LinkedHashMap<>();
279:        jdbc.query("SELECT * FROM sheet_setting_value_history WHERE sheet_id = ? AND setting_key = ? AND made_on <= ?"
280:                        + " ORDER BY id",
281:                (rs, n) -> new SettingValue(sheetId, key, rs.getObject("from_date", LocalDate.class),
282:                        rs.getBigDecimal("setting_value"), rs.getString("setting_text")),
283:                sheetId, key, day).forEach(value -> byFrom.put(value.getFrom(), value));
284:        return byFrom.values().stream().filter(value -> !value.getFrom().isAfter(on))
285:                .max((a, b) -> a.getFrom().compareTo(b.getFrom()));
286:    }
287:
288:    /** The values recorded for the sheet's dated settings as they stood at the end of a day, by key,
289:     *  each list by from-date: for each from-date, the value last recorded from it by then. */
290:    public Map<String, List<SettingValue>> dated(String sheetId, LocalDate day) {
291:        Map<String, Map<LocalDate, SettingValue>> byKey = new TreeMap<>();
292:        jdbc.query("SELECT * FROM sheet_setting_value_history WHERE sheet_id = ? AND made_on <= ? ORDER BY id",
293:                (rs, n) -> new SettingValue(sheetId, rs.getString("setting_key"),
294:                        rs.getObject("from_date", LocalDate.class), rs.getBigDecimal("setting_value"),
295:                        rs.getString("setting_text")),
296:                sheetId, day).forEach(value -> byKey.computeIfAbsent(value.getKey(), k -> new TreeMap<>())
297:                        .put(value.getFrom(), value));
298:        Map<String, List<SettingValue>> dated = new TreeMap<>();
299:        byKey.forEach((key, byFrom) -> dated.put(key, new ArrayList<>(byFrom.values())));
300:        return dated;
301:    }
302:
303:    /** Keep the sheet's policy date as it is now set (null: blank), with the sheet's today. */
304:    public void policyDateSet(String sheetId) {
305:        jdbc.update("INSERT INTO sheet_policy_date_history (sheet_id, policy_date, made_on)"
306:                + " SELECT id, policy_date, today FROM sheet WHERE id = ?", sheetId);
307:    }
308:
309:    /** The sheet's policy date as it stood set at the end of a day; null when it was blank. */
310:    public LocalDate policyDate(String sheetId, LocalDate day) {
311:        List<LocalDate> set = jdbc.query("SELECT policy_date FROM sheet_policy_date_history WHERE sheet_id = ?"
312:                        + " AND made_on <= ? ORDER BY id DESC LIMIT 1",
313:                (rs, n) -> rs.getObject("policy_date", LocalDate.class), sheetId, day);
314:        return set.isEmpty() ? null : set.get(0);
315:    }
